/**
 * Local Visual-to-DOM Grounding Engine
 * 
 * Runs in the web page content script context.
 * Translates visual coordinates (x, y) generated by the Cloud VLM
 * into deterministic, validated DOM element interactions using
 * elementFromPoint and radial proximity snapping.
 */

const INTERACTIVE_SELECTORS = [
  'button',
  'a[href]',
  'input',
  'textarea',
  'select',
  '[role="button"]',
  '[role="link"]',
  '[role="menuitem"]',
  '[role="tab"]',
  '[role="checkbox"]',
  '[role="radio"]',
  '[role="combobox"]',
  '[tabindex]:not([tabindex="-1"])',
  '[onclick]',
  'summary'
].join(',');

/**
 * Normalizes input coordinates to viewport CSS pixels.
 * Supports:
 * - Normalized [0, 1] space
 * - Millinormalized [0, 1000] space
 * - Direct CSS pixels
 * 
 * @param {number} x 
 * @param {number} y 
 * @returns {{cssX: number, cssY: number}}
 */
export function normalizeToViewportPx(x, y) {
  const vw = typeof window !== 'undefined' ? (window.innerWidth || document?.documentElement?.clientWidth || 1280) : 1280;
  const vh = typeof window !== 'undefined' ? (window.innerHeight || document?.documentElement?.clientHeight || 800) : 800;

  let cssX = Number(x) || 0;
  let cssY = Number(y) || 0;

  // Normalized 0 to 1
  if (cssX <= 1 && cssY <= 1 && cssX >= 0 && cssY >= 0) {
    cssX = Math.round(cssX * vw);
    cssY = Math.round(cssY * vh);
  }
  // Normalized 0 to 1000
  else if (cssX <= 1000 && cssY <= 1000 && (cssX > 1 || cssY > 1)) {
    cssX = Math.round((cssX / 1000) * vw);
    cssY = Math.round((cssY / 1000) * vh);
  }

  // Clamp within current viewport bounds
  cssX = Math.max(0, Math.min(cssX, vw - 1));
  cssY = Math.max(0, Math.min(cssY, vh - 1));

  return { cssX, cssY };
}

/**
 * Checks if an element is an interactive clickable target.
 * @param {Element} el 
 * @returns {boolean}
 */
export function isInteractiveElement(el) {
  if (!el || !(el instanceof Element)) return false;
  return el.matches(INTERACTIVE_SELECTORS) || el.closest(INTERACTIVE_SELECTORS) !== null;
}

/**
 * Resolves the DOM element corresponding to viewport coordinates with radial snapping.
 * 
 * @param {number} x Coordinate X
 * @param {number} y Coordinate Y
 * @param {number} [toleranceRadius=25] Search radius for snapping to nearest interactive element
 * @returns {{element: Element|null, cssX: number, cssY: number, wasSnapped: boolean}}
 */
export function resolveElementFromCoordinates(x, y, toleranceRadius = 25) {
  const { cssX, cssY } = normalizeToViewportPx(x, y);

  let directElement = document.elementFromPoint(cssX, cssY);
  if (!directElement) {
    return { element: null, cssX, cssY, wasSnapped: false };
  }

  // If the direct hit is already interactive or inside an interactive container
  const directInteractive = directElement.closest(INTERACTIVE_SELECTORS);
  if (directInteractive) {
    return { element: directInteractive, cssX, cssY, wasSnapped: false };
  }

  // Proximity radial search for slight coordinate misalignments
  if (toleranceRadius > 0) {
    const steps = [5, 10, 15, 20, toleranceRadius];
    const angles = [0, 45, 90, 135, 180, 225, 270, 315];

    for (const radius of steps) {
      for (const angle of angles) {
        const rad = (angle * Math.PI) / 180;
        const testX = cssX + Math.round(Math.cos(rad) * radius);
        const testY = cssY + Math.round(Math.sin(rad) * radius);

        const candidate = document.elementFromPoint(testX, testY);
        if (candidate) {
          const interactive = candidate.closest(INTERACTIVE_SELECTORS);
          if (interactive) {
            return { element: interactive, cssX: testX, cssY: testY, wasSnapped: true };
          }
        }
      }
    }
  }

  // Fallback to the direct element even if not strictly interactive
  return { element: directElement, cssX, cssY, wasSnapped: false };
}

/**
 * Dispatches a realistic sequence of mouse/pointer events at the given coordinates.
 * 
 * @param {number} x Coordinate X
 * @param {number} y Coordinate Y
 * @returns {{success: boolean, targetTag: string, wasSnapped: boolean}}
 */
export function performClickAtCoordinates(x, y) {
  const { element, cssX, cssY, wasSnapped } = resolveElementFromCoordinates(x, y);
  if (!element) {
    return { success: false, targetTag: '', wasSnapped: false };
  }

  // Focus element if focusable
  if (typeof element.focus === 'function') {
    element.focus();
  }

  const eventOpts = {
    bubbles: true,
    cancelable: true,
    composed: true,
    view: window,
    clientX: cssX,
    clientY: cssY,
    pointerId: 1,
    isPrimary: true
  };

  try {
    element.dispatchEvent(new PointerEvent('pointerdown', eventOpts));
    element.dispatchEvent(new MouseEvent('mousedown', eventOpts));
    element.dispatchEvent(new PointerEvent('pointerup', eventOpts));
    element.dispatchEvent(new MouseEvent('mouseup', eventOpts));
    element.dispatchEvent(new MouseEvent('click', eventOpts));
    return { success: true, targetTag: element.tagName.toLowerCase(), wasSnapped };
  } catch (err) {
    // Fallback native click
    if (typeof element.click === 'function') {
      element.click();
      return { success: true, targetTag: element.tagName.toLowerCase(), wasSnapped };
    }
    return { success: false, targetTag: element.tagName.toLowerCase(), wasSnapped };
  }
}

/**
 * Focuses and types text into the element at the given coordinates.
 * 
 * @param {number} x Coordinate X
 * @param {number} y Coordinate Y
 * @param {string} text Text to type
 * @param {boolean} [clearFirst=false]
 * @returns {{success: boolean, targetTag: string}}
 */
export function performTypeAtCoordinates(x, y, text = '', clearFirst = false) {
  const { element } = resolveElementFromCoordinates(x, y);
  if (!element) {
    return { success: false, targetTag: '' };
  }

  if (typeof element.focus === 'function') {
    element.focus();
  }

  const isInputOrTextArea = element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement;
  const isContentEditable = element.isContentEditable;

  if (isInputOrTextArea) {
    if (clearFirst) {
      element.value = '';
    }
    element.value += text;
    element.dispatchEvent(new Event('input', { bubbles: true }));
    element.dispatchEvent(new Event('change', { bubbles: true }));
    return { success: true, targetTag: element.tagName.toLowerCase() };
  } else if (isContentEditable) {
    if (clearFirst) {
      element.textContent = '';
    }
    element.textContent += text;
    element.dispatchEvent(new Event('input', { bubbles: true }));
    return { success: true, targetTag: element.tagName.toLowerCase() };
  }

  return { success: false, targetTag: element.tagName.toLowerCase() };
}
